#include "KS/SRC/stringx.h"

extern "C" int sprintf(char *, const char *, ...);
extern "C" char *strcat(char *, const char *);

class entity_anim_tree;
class entity_track_tree
{
public:
  static const char *extension(void);
};

class entity
{
public:
  void load_anim(const stringx &filename) const;
  entity_anim_tree *play_anim(int slot, const stringx &filename, float start_time, unsigned short anim_flags = 0, short loop = -1);
};

bool file_finder_exists(const stringx &filename, const stringx &extension, stringx *found_name = 0);

enum { ANIM_PRIMARY = 0, ANIM_NONCOSMETIC = 0x0200 };

class generic_anim
{
public:
  generic_anim(const stringx& path, const stringx& name) { my_base_name = name; dummy = false; cur_state = cur_anim = 0; left_down = right_down = false; }
  virtual ~generic_anim() { }
  virtual void update(bool collide, bool jump, bool spray, float *alpha) = 0;
  virtual void spawn() = 0;
  virtual void switch_anims() = 0;
protected:
  stringx my_base_name;
  int cur_state, cur_anim;
  bool dummy;
  bool left_down, right_down;
};

class generic_anim_misc : public generic_anim
{
public:
  generic_anim_misc(entity **entities, const stringx& path, const stringx& name, const char **prefixes, int count);
  void construct(entity **entities, const stringx& path, const stringx& name, const char **prefixes, int count);
  virtual ~generic_anim_misc();
  void update(bool collide, bool jump, bool spray, float *alpha);
  void spawn();
  void switch_anims();
private:
  static const char* generic_anim_names[];
  int generic_anims[5];
  int generic_anim_state;
  int items_count;
  stringx* items_prefixes;
  entity **my_entities;
};

void generic_anim_misc::construct (entity **entities, const stringx& path, const stringx& name, const char **prefixes, int count)
{
	int i, j;

	items_count = count;
	items_prefixes = new stringx[count];
	my_entities = new entity* [count];

	for (i = 0; i < count; i++)
	{
		if (i != 0)
			items_prefixes[i] = prefixes[i];
		my_entities[i] = entities[i];
	}

	for (i = 0; i < 5; i++)
	{
		generic_anims[i] = 0;

		for (;;)
	  {
			for (j = 0; j < count; j++)
			{
				char anim[256];
				bool play = (i == 0);

				if (j == 0)
					sprintf (anim, "%s\\ANIMATIONS\\%s_%s_%d", path.c_str(), name.c_str(), generic_anim_names[i], generic_anims[i] + 1);
				else
					sprintf (anim, "%s\\ANIMATIONS\\%s_%s_%s_%d", path.c_str(), name.c_str(), prefixes[j], generic_anim_names[i], generic_anims[i] + 1);

				if (file_finder_exists (anim, entity_track_tree::extension ()))
		    {
					strcat (anim, entity_track_tree::extension ());
					my_entities[j]->load_anim (anim);

					if (play)
					{
					  my_entities[j]->play_anim (ANIM_PRIMARY, anim, 0, ANIM_NONCOSMETIC);
						play = false;
					}
				}
		    else
					break;
			}

			if (j == count)
				generic_anims[i]++;
			else
				break;
	  }
	}
}
